function getValidJsonObject(rawText) {

    if (typeof rawText !== 'string' || rawText.trim() === '') {
        console.error("Invalid input or empty text field.");
        return null;
    }

    let jsonString = rawText.trim();

    // 2. Check for and remove the markdown JSON block fences.
    // This regex is robust and handles variations in whitespace.
    const markdownRegex = /^```json\s*([\s\S]*?)\s*```$/;
    const match = jsonString.match(markdownRegex);

    if (match) {
        // If it's a match, the actual JSON string is in the first capture group.
        jsonString = match[1];
    }

    // 3. Parse the cleaned string into a JSON object.
    try {
        return JSON.parse(jsonString);
    } catch (error) {
        console.error("Failed to parse JSON string:", error);
        console.error("Problematic string:", jsonString);
        return null;
    }
}
return getValidJsonObject($input.first().json.content.parts[0].text);

let prompts = [];
let idx = 1;
for (const item of $input.first().json.prompts) {
  let payload = {
    "url": "https://api.kie.ai/api/v1/jobs/createTask",
    "config": {
      "model": "gpt-image-2-5-flare-text-to-image",
      "input": {
        "prompt": item.prompt,
        "aspect_ratio": $('Prepare Data').first().json.config.aspect_ratio,
        "resolution": "1K",
        "background": "auto"
       }
    } 
  }
  if(item.relevantImg.length > 0){
    payload.config.model ='gpt-image-2-5-flare-image-to-image';
    payload.config.input.input_urls = item.relevantImg
    .map(key => $('Prepare Image').first().json.images.find(image => image.key === key)?.url)
    .filter(Boolean);
  }
  prompts.push({
    filename: "eventAgentResult/eventAgentResult-"+$('Prepare Data').first().json.agent_id+"-img"+idx+".jpg",
    payload: payload
  });
  idx++;
}

return prompts;

